const norm = v => String(v || '').trim().toLowerCase();
const row = rows.find(r => norm(r.source_name) === src)
         || rows.find(r => norm(r.source_name) === 'default')
         || rows[0];
if (!row) return [];
return [{ json: { ...row, profile_match: norm(row.source_name) === src ? 'exact' : 'fallback' } }];

// Code node "Build escalation"  (Mode: Run Once for Each Item)
// Input item = residents sheet row (from "Profile lookup 2"); payload via $('Webhook').
const row  = $input.item.json;
const body = $('Webhook').first().json.body;
const ep   = body.episode;
const pb   = ep.posture_breakdown_sec || {};
const level = body.alert_level;                         // 2 or 3 (top-level field on escalation events)
const head  = (ep.event_features && ep.event_features.head_impact) ? ep.event_features.head_impact.risk : 'unknown';

const lead = level === 3
  ? `🚨 EMERGENCY — no recovery after ${ep.thresholds.level3_sec} s`
  : `⚠️ STILL DOWN — ${ep.thresholds.level2_sec} s on the floor`;

const text =
  `${lead}\n` +
  `${row.resident_name || body.source.name} · ${body.source.name}\n` +
  `On the floor: ${Math.round(ep.time_on_ground_sec)} s (lying ${Math.round(pb.lying || 0)} s, motionless ${Math.round(ep.time_motionless_sec || 0)} s, out of view ${Math.round(pb.not_visible || 0)} s)\n` +
  `Head-impact risk: ${head}\n` +
  (level === 3
    ? `Check on them now. If not responsive or unable to get up: call 000.`
    : `Please check on them now.`);

// Telegram parse mode is HTML: escape the three characters that break it.
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---- v10: media for Telegram -------------------------------------------
// The app adds body.clip.mp4_base64 (short H.264 clip around the fall) and
// body.snapshots.fall_frame_jpeg_base64 when those options are ticked.
// The chain after this node sends video > photo > plain text, whichever exists.
const clipB64  = (body.clip && body.clip.mp4_base64) || null;
const photoB64 = (body.snapshots && body.snapshots.fall_frame_jpeg_base64) || null;
const clipNote = body.clip
  ? `\nClip: ${body.clip.pre_fall_sec != null ? body.clip.pre_fall_sec + ' s before' : ''}` +
    `${body.clip.post_fall_sec != null ? ' to ' + body.clip.post_fall_sec + ' s after the fall' : ''}`
  : '';

return ({ json: {
  chat_id: row.carer_telegram_chat_id,
  text: esc(text + clipNote).slice(0, 1000),
  clip_b64: clipB64,
  photo_b64: photoB64,
} });

