// Answer POSTed by the FallGuard app (Actions page) to the Wait node's resume URL.
const b = $('Wait post-fall check').first().json.body || {};
return { json: b };

// Code node "Build transfer pack"  (Mode: Run Once for Each Item)
// Runs on the "Call 000" branch after the caregiver form.
// Reads: $('Assemble') (body + profile), $('Grading'), $('Caregiver form').
// Output: { subject, text } for the Gmail node.
const a    = $('Assemble').first().json;
const body = a.body, p = a.profile || {};
const ep   = body.episode, pb = ep.posture_breakdown_sec || {};
const g    = $('Grading').first().json.grading || {};
const f    = $('Caregiver form').first().json || {};
const ef   = ep.event_features || {}, pre = ef.prefall || {}, head = ef.head_impact || {};

const isbar = [
  'ISBAR HANDOVER — FALL (from FallGuard camera record)',
  '',
  `I  Identify: ${p.resident_name || '(name)'}, DOB ${p.dob || '(dob)'}, ${p.address || body.source.name}. Caller: carer.`,
  `S  Situation: Fall detected ${ep.fall_time}. Outcome so far: ${ep.status}. On the floor ${g.summary_numbers?.time_on_ground || Math.round(ep.time_on_ground_sec) + ' s'}` +
    ` (lying ${g.summary_numbers?.time_lying || Math.round(pb.lying || 0) + ' s'}, motionless ${g.summary_numbers?.time_motionless || Math.round(ep.time_motionless_sec || 0) + ' s'}).`,
  `B  Background: Fell ${g.fall_height_words || 'from ' + (pre.fall_height_category || 'unknown').replace(/_/g, ' ')}.` +
    ` Anticoagulant / antiplatelet: ${p.anticoagulant || 'unknown'}. ACD on file: ${p.acd_on_file || 'unknown'} (carer reviewed: ${f['ACD reviewed'] || 'n/a'}). GP: ${p.gp_name || ''} ${p.gp_phone || ''}.`,
  `A  Assessment (carer, at scene): injury ${f['Injury seen'] || 'n/a'}; alert ${f['Alert and responsive'] || 'n/a'}; pain ${f['Pain'] || 'n/a'}; can stand ${f['Can stand and walk'] || 'n/a'}.` +
    ` Camera analysis rates the risk that the head struck the floor as ${head.risk || 'unknown'} (${(head.reasons || []).join('; ') || 'no basis recorded'}). This is an estimate, not a diagnosis.`,
  `R  Recommendation: carer decided "${f['Decision'] || 'Call 000'}". Please assess for head injury and long-lie complications as clinically indicated.`,
  '',
  'TRANSFER PACK — take with the person:',
  '  [ ] Medicare card  [ ] concession card (Pensioner / Health Care / Seniors Health / DVA)  [ ] private-insurance card if any',
  '  [ ] current medication list or the medications themselves  [ ] allergy list',
  '  [ ] advance care directive copy  [ ] enduring guardian / guardianship papers',
  `  [ ] GP details: ${p.gp_name || ''} ${p.gp_phone || ''}  [ ] emergency contact: ${p.supporter_name || ''} ${p.supporter_email || ''}`,
  '  [ ] glasses, hearing aids, dentures, walking aid  [ ] phone and charger',
  '  [ ] this page',
  '',
  'Do NOT write the Medicare number, IHI or insurance membership number in messages; the cards go with the person.',
].join('\n');

return { json: { subject: `FALL — ${p.resident_name || body.source.name}: transfer pack and ISBAR`, text: isbar } };

// Answer POSTed by the FallGuard app (Actions page) to the Wait node's resume URL.
const b = $('Wait supporter approval').first().json.body || {};
return { json: { data: { approved: b.approved === true || String(b.approved).toLowerCase() === 'true', decided_by: b.decided_by || '', decided_at: b.decided_at || '' } } };

// Answer POSTed by the FallGuard app (Actions page) to the Wait node's resume URL.
const b = $('Wait outcome').first().json.body || {};
return { json: b };

// Code node "Incident draft"  (Mode: Run Once for Each Item)
// Runs after the outcome form. Pre-fills what the camera record knows and leaves the
// clinical fields for a person. Output: { subject, text, row } — text for Gmail, row for Sheets.
const a    = $('Assemble').first().json;
const body = a.body, p = a.profile || {};
const ep   = body.episode, pb = ep.posture_breakdown_sec || {};
const g    = $('Grading').first().json.grading || {};
const f1   = $('Caregiver form').first().json || {};
const f2   = $('Outcome form').first().json || {};
const ef   = ep.event_features || {}, pre = ef.prefall || {}, head = ef.head_impact || {};

const alerts = (ep.alerts || []).map(x => `  - Level ${x.level} ${x.label} at ${x.time} (${x.time_on_ground_sec} s on floor)`).join('\n');
const text = [
  `INCIDENT REPORT — DRAFT (pre-filled by FallGuard; fields marked [ ] need a person)`,
  ``,
  `Person: ${p.resident_name || ''}   DOB: ${p.dob || ''}   Location: ${p.address || body.source.name}`,
  `Event: fall detected ${ep.fall_time} (video time ${ep.fall_video_time_sec} s), episode ${ep.episode_id}`,
  `Witnessed: camera record exists (source ${body.source.name}); human witness: [ ]`,
  ``,
  `What the camera recorded`,
  `  Fell ${g.fall_height_words || 'from ' + (pre.fall_height_category || 'unknown')}; pre-fall posture ${pre.posture || 'unknown'}.`,
  `  Time on the floor ${Math.round(ep.time_on_ground_sec)} s: lying ${Math.round(pb.lying || 0)} s, partially upright ${Math.round(pb.partially_upright || 0)} s, out of view ${Math.round(pb.not_visible || 0)} s; motionless ${Math.round(ep.time_motionless_sec || 0)} s.`,
  `  Outcome of episode: ${ep.status} (${ep.status === 'recovered' ? 'got up and stayed upright' : 'recording ended while still down'}).`,
  `  Head-impact risk rating: ${head.risk || 'unknown'} — ${(head.reasons || []).join('; ')}`,
  `  Fall confirmed by camera: ${ef.fall_confidence || 'unconfirmed'}`,
  `  Alerts sent:\n${alerts || '  - none'}`,
  ``,
  `Carer assessment at scene: injury ${f1['Injury seen'] || '[ ]'}; alert ${f1['Alert and responsive'] || '[ ]'}; pain ${f1['Pain'] || '[ ]'}; can stand ${f1['Can stand and walk'] || '[ ]'}; ACD reviewed ${f1['ACD reviewed'] || '[ ]'}; decision ${f1['Decision'] || '[ ]'}; notes ${f1['Notes'] || ''}`,
  `Outcome: ${f2['Outcome'] || '[ ]'}; hospital ${f2['Hospital'] || ''}; notes ${f2['Notes'] || ''}`,
  ``,
  `Fields a person must complete`,
  `  [ ] Injuries found by a clinician (site, severity)`,
  `  [ ] Immediate actions taken (how lifted, first aid)`,
  `  [ ] Likely cause and environment (floor, footwear, lighting, medication changes, night toileting)`,
  `  [ ] Who was notified and when (family, GP, ambulance) — camera log: see event_log sheet`,
  `  [ ] Meets the QI Program "major injury" definition? (fracture, dislocation, closed head injury with altered consciousness, subdural haematoma)`,
  `  [ ] SIRS reportable category, priority and reasoning — provider decision; NOT automated`,
  `  [ ] Care-plan changes`,
].join('\n');

const row = {
  episode_id: ep.episode_id, resident: p.resident_name || '', fall_time: ep.fall_time,
  time_on_ground_sec: ep.time_on_ground_sec, head_risk: head.risk || 'unknown',
  fall_height: pre.fall_height_category || 'unknown', fall_confidence: ef.fall_confidence || '',
  decision: f1['Decision'] || '', outcome: f2['Outcome'] || '', tier: g.tier_label || '',
  draft_created_at: new Date().toISOString(),
};
return { json: { subject: `Incident report draft — ${p.resident_name || body.source.name} — ${ep.fall_time}`, text, row } };

// Code node "Select blocks"  (Mode: Run Once for All Items)
// Input items = ALL rows of the education_blocks sheet (columns: key, lang, title, text, source).
// Picks the blocks that match the episode's state and returns ONE item with the ordered blocks.
const rows = $input.all().map(i => i.json);
const a    = $('Assemble').first().json;
const p    = a.profile || {};
const ep   = a.body.episode;
const ef   = ep.event_features || {}, head = ef.head_impact || {};
const f2   = $('Outcome form').first().json || {};
const lang = (p.language || 'en').toLowerCase();

const keys = ['after_a_fall_basics'];
if (['high', 'medium'].includes(head.risk)) keys.push('head_injury_watch');
if (String(p.anticoagulant).toLowerCase().startsWith('y')) keys.push('anticoagulant_warning');
if (ep.time_on_ground_sec >= (ep.thresholds?.level2_sec || 10) || ep.status !== 'recovered') keys.push('cannot_get_up');
if (['Admitted', 'ED then home'].includes(f2['Outcome'] || '')) keys.push('after_hospital');   // discharge / after-hospital care for both ways home
keys.push('prevent_next_fall', 'when_to_call');

const pick = k => rows.find(r => r.key === k && (r.lang || 'en').toLowerCase() === lang)
                || rows.find(r => r.key === k && (r.lang || 'en').toLowerCase() === 'en');
const blocks = keys.map(pick).filter(Boolean);

return [{ json: {
  resident_name: p.resident_name || '', language: lang, keys,
  blocks_text: blocks.map(b => `## ${b.title}\n${b.text}\n(Source: ${b.source})`).join('\n\n'),
} }];

// Answer POSTed by the FallGuard app (Actions page) to the Wait node's resume URL.
const b = $('Wait sheet approval').first().json.body || {};
return { json: { data: { approved: b.approved === true || String(b.approved).toLowerCase() === 'true', decided_by: b.decided_by || '', decided_at: b.decided_at || '' } } };
